Lemma combined_miss_backP : forall (fra sp gp tp t0 t1 t2 fs0 fs1 fs2 fs3 fs4 a1 a2 a3 a4 a5 a6 a7 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
    (F : bvmap 5 word) (fc : bv 32) (m : mem) (lo c CA sb cnt mc : Z) (chunks : list Z) (j0 j1 j2 j3 : word) (P : Z),
  P = CA + 80 * c ->
  mem_inv bsegs m -> stk bsegs m lo (bv_unsigned sp + -48) -> aceil <= lo -> lo + 48 <= bv_unsigned sp -> bv_unsigned sp mod 16 = 0 ->
  rw_cells bsegs m (bv_unsigned sp + -48) [C8 fs4; C8 fs3; C8 fs2; C8 fs1; C8 fs0; C8 fra] ->
  1 <= c < 32 -> akobj CA 2592 /\ CA + 2592 <= aceil /\ CA mod 16 = 0 -> 0 <= sb /\ sb + kSpaceSize <= aceil ->   (* [comment removed for export] *)
  rw_cells bsegs m (AINST + 32) [C8 (wz sb)] ->
  rw_cells bsegs m P [C4 (wz cnt); C4 (wz mc)] -> rw_cells bsegs m (P + 8) [C8 (wz (class_size c))] ->
  u32arr bsegs m (P + 16) (wlist (rev chunks)) -> cnt = zlen chunks -> 1 <= cnt <= 16 ->
  stk bsegs m (P + 16 + 4 * cnt) (P + 80) -> Forall (fun cp => 0 <= cp < 2^32) chunks ->
  rw_cells bsegs m (CA + 2560) [C8 j0; C8 j1; C8 j2; C8 j3] ->
  evt bsegs (combined_hit_post fra sp gp tp fs0 fs1 fs2 fs3 fs4 s5 s6 s7 s8 s9 s10 s11 F fc m lo P CA c sb cnt mc chunks)
    (MS (mkR (wz 0x54ac4) (Z_to_bv 64 (bv_unsigned sp + -48)) gp tp t0 t1 t2 (Z_to_bv 64 c) (Z_to_bv 64 P) (wz 1) a1 a2 a3 a4 a5 a6 a7
             (Z_to_bv 64 8) (Z_to_bv 64 CA) (Z_to_bv 64 AINST) s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 0x54ac4) fc None m (seg_rom bsegs)).
